'use client';

import React from 'react';

/** Theme for the TerminalPanel. */
export type TerminalPanelTheme = 'terminal' | 'brutal';

/** Props for the {@link TerminalPanel} component. */
export interface TerminalPanelProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Title displayed in the panel header. */
  title?: string;
  /** Theme variant. */
  theme?: TerminalPanelTheme;
  /** Whether to show the traffic-light action buttons. */
  showActions?: boolean;
  /** Called when the close action is clicked. */
  onClose?: () => void;
  /** Called when the minimize action is clicked. */
  onMinimize?: () => void;
  /** Called when the maximize action is clicked. */
  onMaximize?: () => void;
  /** Additional CSS class names. */
  className?: string;
  /** Terminal body content. */
  children?: React.ReactNode;
}

/**
 * Code execution terminal panel with ASCII borders.
 * Renders header with traffic-light buttons and a body with scanline overlay.
 */
export const TerminalPanel = React.forwardRef<HTMLDivElement, TerminalPanelProps>(
  (
    { title = 'terminal', theme, showActions = true, onClose, onMinimize, onMaximize, className, children, ...rest },
    ref,
  ) => (
    <div
      ref={ref}
      className={`sk-terminal-panel${className ? ` ${className}` : ''}`}
      data-theme={theme}
      {...rest}
    >
      <div className="sk-terminal-panel__header">
        <span className="sk-terminal-panel__title">{title}</span>
        {showActions && (
          <div className="sk-terminal-panel__actions">
            <button
              className="sk-terminal-panel__action sk-terminal-panel__action--close"
              aria-label="Close"
              onClick={onClose}
            />
            <button
              className="sk-terminal-panel__action sk-terminal-panel__action--minimize"
              aria-label="Minimize"
              onClick={onMinimize}
            />
            <button
              className="sk-terminal-panel__action sk-terminal-panel__action--maximize"
              aria-label="Maximize"
              onClick={onMaximize}
            />
          </div>
        )}
      </div>
      <div className="sk-terminal-panel__body">{children}</div>
    </div>
  ),
);

TerminalPanel.displayName = 'TerminalPanel';

/**
 * skeehn — TerminalPanel Component
 *
 * @component sk-terminal-panel
 * @slots     __header __title __actions __action __body __prompt __command __output __input __input-field
 * @a11y      Semantic output regions, keyboard input, focus ring on input
 * @design    Real chrome, bigger traffic lights, readable body, stronger scanlines,
 *            phosphor caret. Brutal theme makes the frame 2px.
 */

.sk-terminal-panel { border: var(--sk-border); border-radius: var(--sk-radius-md); overflow: hidden; font-family: var(--sk-font-mono); margin-bottom: var(--sk-space-3); box-shadow: var(--sk-panel-shadow); }
.sk-terminal-panel__header { display: flex; align-items: center; justify-content: space-between; padding: var(--sk-space-2) var(--sk-space-3); background: hsl(var(--sk-muted)); border-bottom: var(--sk-border); }
.sk-terminal-panel__title { font-size: var(--sk-font-size-xs); font-weight: 600; letter-spacing: var(--sk-letter-spacing-wide); text-transform: uppercase; color: hsl(var(--sk-muted-foreground)); }
.sk-terminal-panel__actions { display: flex; gap: var(--sk-space-1); }
.sk-terminal-panel__action { width: 0.85rem; height: 0.85rem; border-radius: 50%; border: none; cursor: pointer; transition: opacity var(--sk-transition-fast), transform var(--sk-transition-fast); }
.sk-terminal-panel__action:hover { transform: scale(1.12); }
.sk-terminal-panel__action--close { background: hsl(var(--sk-destructive)); }
.sk-terminal-panel__action--minimize { background: hsl(var(--sk-warning)); }
.sk-terminal-panel__action--maximize { background: hsl(var(--sk-success)); }

.sk-terminal-panel__body { padding: var(--sk-space-3); background: hsl(var(--sk-surface)); font-size: var(--sk-font-size-sm); line-height: 1.7; position: relative; }
.sk-terminal-panel__body::before { content: ""; position: absolute; inset: 0; background-image: var(--sk-dither-scanlines); background-size: 100% 3px; background-repeat: repeat; opacity: 0.12; pointer-events: none; }
.sk-terminal-panel__body > * { position: relative; z-index: 1; }
.sk-terminal-panel__prompt { color: hsl(var(--sk-success)); font-weight: 600; }
.sk-terminal-panel__command { color: hsl(var(--sk-foreground)); }
.sk-terminal-panel__output { color: hsl(var(--sk-muted-foreground)); margin: var(--sk-space-1) 0; white-space: pre-wrap; overflow-x: auto; }

.sk-terminal-panel__input { display: flex; align-items: center; gap: var(--sk-space-2); padding: var(--sk-space-2) var(--sk-space-3); border-top: var(--sk-border); background: hsl(var(--sk-muted) / 0.4); }
.sk-terminal-panel__input:focus-within { outline: var(--sk-focus-ring); outline-offset: -2px; }
.sk-terminal-panel__input-field { flex: 1; border: none; background: transparent; font-family: var(--sk-font-mono); font-size: var(--sk-font-size-sm); color: hsl(var(--sk-foreground)); outline: none; caret-color: hsl(var(--sk-success)); }

.sk-terminal-panel[data-theme="terminal"] { border-color: hsl(var(--sk-success) / 0.3); }
.sk-terminal-panel[data-theme="terminal"] .sk-terminal-panel__prompt { color: hsl(var(--sk-success)); }
.sk-terminal-panel[data-theme="brutal"] { border-width: 2px; }

/* Loading & skeleton */
.sk-terminal-panel[data-loading] .sk-terminal-panel__body { position: relative; opacity: 0.5; }
.sk-terminal-panel[data-loading] .sk-terminal-panel__body::after { content: ""; position: absolute; inset: 0; background-image: var(--sk-dither-pattern); background-repeat: repeat; opacity: var(--sk-dither-opacity-normal); animation: sk-pulse-dither 1.5s ease-in-out infinite; pointer-events: none; }
.sk-terminal-panel[data-skeleton] .sk-terminal-panel__body {
  min-height: 4rem;
  background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-secondary)) 50%, hsl(var(--sk-muted)) 75%);
  background-size: 200% 100%; animation: sk-shimmer 1.8s ease-in-out infinite;
}
.sk-terminal-panel[data-skeleton] .sk-terminal-panel__body > * { visibility: hidden; }
.sk-terminal-panel[data-skeleton] .sk-terminal-panel__body::before { display: none; }

@media print {
  .sk-terminal-panel { border: 1px solid hsl(var(--sk-foreground)); box-shadow: none; break-inside: avoid; }
  .sk-terminal-panel__actions, .sk-terminal-panel__body::before, .sk-terminal-panel__input { display: none; }
  .sk-terminal-panel[data-skeleton] { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .sk-terminal-panel__action { transition: none; }
  .sk-terminal-panel[data-loading] .sk-terminal-panel__body::after { animation: none; }
  .sk-terminal-panel[data-skeleton] .sk-terminal-panel__body { animation: none; background: hsl(var(--sk-muted)); }
}
